// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.security.auth/** * NOUS — Biometric availability (Module 12, Pillar 3). * * Strategy §12.3 — result of [AuthenticationManager.checkBiometricAvailability]: * *   - **NOT_AVAILABLE** — device has no biometric hardware, or the hardware *     is unavailable (e.g., biometric sensor failed). NOUS cannot use *     biometric auth; PIN is the only option. *   - **AVAILABLE_NO_ENROLLMENT** — device has biometric hardware but the *     user hasn't enrolled any biometric (no fingerprint, no face). NOUS *     prompts the user to enroll before biometric auth can be used. *   - **AVAILABLE_ENROLLED** — biometric hardware present AND user has at *     least one biometric enrolled. NOUS can use [BiometricPrompt]. * * Detected via `BiometricManager.from(context).canAuthenticate(BIOMETRIC_STRONG)`: *   - `BIOMETRIC_SUCCESS` → AVAILABLE_ENROLLED *   - `BIOMETRIC_ERROR_NO_HARDWARE` / `BIOMETRIC_ERROR_HW_UNAVAILABLE` → NOT_AVAILABLE *   - `BIOMETRIC_ERROR_NONE_ENROLLED` → AVAILABLE_NO_ENROLLMENT */enum class BiometricAvailability {    NOT_AVAILABLE,    AVAILABLE_NO_ENROLLMENT,    AVAILABLE_ENROLLED,}/** * NOUS — Biometric auth result (Module 12, Pillar 3). * * Strategy §12.3 — sealed result of [AuthenticationManager.authenticateBiometric]: * *   - **SUCCESS** — biometric (fingerprint/face) recognized. *   - **FAILED** — biometric NOT recognized (wrong finger/face). User can retry. *   - **ERROR** — unrecoverable error (e.g., hardware failure, lockout, *     user canceled via negative button). Includes error code + message. *   - **CANCELLED** — user explicitly cancelled (back press, screen off). */sealed interface BiometricAuthResult {    /**     * Biometric authentication succeeded.     *     * @param cryptoCipher if the [BiometricPrompt] was associated with a     *   `CryptoObject`, the authenticated cipher is returned here (used     *   for Keystore key use authentication — see [KeystoreManager.generateKey]     *   with `requireAuth = true`).     */    data class Success(        val cryptoCipher: javax.crypto.Cipher? = null,    ) : BiometricAuthResult    /** Biometric not recognized — user can retry. */    data object Failed : BiometricAuthResult    /**     * Unrecoverable error.     *     * @param errorCode one of `BiometricPrompt.BIOMETRIC_ERROR_*` constants.     * @param errorMessage human-readable message (localized).     */    data class Error(        val errorCode: Int,        val errorMessage: String,    ) : BiometricAuthResult    /** User cancelled (back press, "Cancel" button, screen off). */    data object Cancelled : BiometricAuthResult}/** * NOUS — PIN verification result (Module 12, Pillar 3). * * Strategy §12.3 — sealed result of [AuthenticationManager.verifyPin]: * *   - **SUCCESS** — PIN matches the stored Argon2 hash. *   - **WRONG_PIN** — PIN does not match. User can retry (subject to lockout). *   - **LOCKED_OUT** — too many failed attempts; user must wait [retryAfterSeconds] *     before trying again. Triggered after 5 failures in 10 minutes (per *     Strategy §12.8 brute-force defense). */sealed interface PinVerificationResult {    data object Success : PinVerificationResult    data object WrongPin : PinVerificationResult    /**     * @param retryAfterSeconds seconds until the user can retry.     * @param failedAttemptCount total failed attempts in the lockout window.     */    data class LockedOut(        val retryAfterSeconds: Long,        val failedAttemptCount: Int,    ) : PinVerificationResult}/** * NOUS — Recommended auth method (Module 12, Pillar 3). * * Strategy §12.3 — [AuthenticationManager.getRecommendedAuthMethod] returns * the most secure available method, in priority order: * *   1. **BIOMETRIC** (highest — hardware-bound, can't be phished) *   2. **PASSKEY** (FIDO2/WebAuthn — passwordless, hardware-bound) *   3. **PIN** (lowest — but offline; requires Argon2 hash protection) *   4. **NONE** (no method configured — app lock disabled) */enum class RecommendedAuthMethod {    NONE,    PIN,    PASSKEY,    BIOMETRIC,}